BEGIN;
SELECT plan(27);
INSERT INTO households(id,name)VALUES('e1000000-0000-4000-8000-000000000001','synthetic sleep household A'),('e1000000-0000-4000-8000-000000000002','synthetic sleep household B');
INSERT INTO auth.users(id,email)VALUES('e1000000-0000-4000-8000-000000000003','sleep-user@example.invalid'),('e1000000-0000-4000-8000-000000000004','sleep-other@example.invalid');
UPDATE profiles SET household_id='e1000000-0000-4000-8000-000000000001',is_approved=true,role='owner' WHERE id='e1000000-0000-4000-8000-000000000003';
UPDATE profiles SET household_id='e1000000-0000-4000-8000-000000000002',is_approved=true WHERE id='e1000000-0000-4000-8000-000000000004';
INSERT INTO children(id,household_id,name)VALUES('e1000000-0000-4000-8000-000000000005','e1000000-0000-4000-8000-000000000001','synthetic sleep sibling');
CREATE TEMP TABLE sleep_test(value jsonb);GRANT ALL ON sleep_test TO authenticated;
CREATE TEMP TABLE share_sleep(value jsonb);GRANT ALL ON share_sleep TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
INSERT INTO sleep_test SELECT start_sleep('e1000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),now()-interval '2 hours');
SELECT is((SELECT value->>'status' FROM sleep_test),'saved','start is saved');
SELECT is((start_sleep('e1000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),now()-interval '2 hours')->>'status'),'replayed','same frozen start id replays');
SELECT is((start_sleep('e1000000-0000-4000-8000-000000000007',(SELECT id FROM children WHERE is_legacy))->>'status'),'conflict','another device cannot start a second active session');
SELECT throws_ok($$SELECT start_sleep('e1000000-0000-4000-8000-000000000006','e1000000-0000-4000-8000-000000000005')$$,'23505',NULL,'same request id cannot change child');
SELECT is((start_sleep('e1000000-0000-4000-8000-000000000007','e1000000-0000-4000-8000-000000000005')->>'status'),'saved','sibling has an independent timer');
SELECT is((SELECT count(*) FROM sleep_sessions WHERE ended_at IS NULL),1::bigint,'default raw read is legacy child only');
SELECT is((stop_sleep('e1000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),'2020-01-01T00:00:00Z','e1000000-0000-4000-8000-000000000008')->>'status'),'conflict','stale stop version cannot overwrite');
UPDATE sleep_test SET value=stop_sleep('e1000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),(value->'session'->>'updated_at')::timestamptz,'e1000000-0000-4000-8000-000000000008');
SELECT is((SELECT value->>'status' FROM sleep_test),'saved','stop commits one end time');
SELECT is((stop_sleep('e1000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),'2020-01-01T00:00:00Z','e1000000-0000-4000-8000-000000000008')->>'status'),'replayed','ambiguous stop confirms the same token');
SELECT throws_ok($$SELECT stop_sleep('e1000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),'2020-01-01T00:00:00Z','e1000000-0000-4000-8000-000000000008',now())$$,'23505',NULL,'same stop token cannot change its payload');
SELECT is((stop_sleep('e1000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),'2020-01-01T00:00:00Z','e1000000-0000-4000-8000-000000000009')->>'status'),'conflict','a second stop cannot move the recorded end');
SELECT ok((SELECT ended_at>started_at FROM sleep_sessions WHERE id='e1000000-0000-4000-8000-000000000006'),'completed session has a positive duration');
SELECT is((start_sleep('e1000000-0000-4000-8000-000000000010',(SELECT id FROM children WHERE is_legacy),now()-interval '90 minutes',now()-interval '60 minutes')->>'status'),'conflict','overlapping completed intervals are not duplicated');
UPDATE sleep_test SET value=edit_sleep('e1000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),(value->'session'->>'updated_at')::timestamptz,now()-interval '3 hours',now()-interval '2 hours','synthetic edited sleep',false);
SELECT is((SELECT value->>'status' FROM sleep_test),'saved','completed time can be edited with its version');
SELECT is((edit_sleep('e1000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),'2020-01-01T00:00:00Z',now()-interval '4 hours',now()-interval '3 hours',NULL,false)->>'status'),'conflict','stale edit cannot replace current interval');
UPDATE sleep_test SET value=edit_sleep('e1000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),(value->'session'->>'updated_at')::timestamptz,now()-interval '3 hours',now()-interval '2 hours','synthetic edited sleep',true);
SELECT ok((SELECT voided FROM sleep_sessions WHERE id='e1000000-0000-4000-8000-000000000006'),'voiding retains historical row');
SELECT throws_ok($$SELECT start_sleep('e1000000-0000-4000-8000-000000000011',(SELECT id FROM children WHERE is_legacy),now(),now()-interval '1 minute')$$,'22023',NULL,'negative interval rejected');
SELECT throws_ok($$UPDATE sleep_sessions SET ended_at=now()$$,'42501',NULL,'client cannot bypass version RPC with a direct update');
SELECT throws_ok($$DELETE FROM sleep_sessions$$,'42501',NULL,'history has no direct delete grant');
SELECT set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM sleep_sessions),0::bigint,'other household cannot read sessions');
SELECT throws_ok($$SELECT stop_sleep('e1000000-0000-4000-8000-000000000006','e1000000-0000-4000-8000-000000000005',now(),'e1000000-0000-4000-8000-000000000012')$$,'42501',NULL,'other household cannot stop a timer');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
INSERT INTO share_sleep SELECT create_child_share('e1000000-0000-4000-8000-000000000005',true,false,false,false,NULL);
SELECT set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
SELECT accept_child_share((SELECT value->>'token' FROM share_sleep));
SELECT is((SELECT jsonb_array_length(shared_child_snapshot((value->>'id')::uuid)->'sleep') FROM share_sleep),1,'explicit daily sharing returns only the selected child sleep');
SELECT is((SELECT count(*) FROM sleep_sessions),0::bigint,'cross-household sharing never opens raw sleep rows');
RESET ROLE;
UPDATE profiles SET role='viewer' WHERE id='e1000000-0000-4000-8000-000000000003';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM sleep_sessions),0::bigint,'viewer cannot read raw sleep');
SELECT throws_ok($$SELECT start_sleep('e1000000-0000-4000-8000-000000000013','e1000000-0000-4000-8000-000000000005')$$,'42501',NULL,'viewer cannot write through RPC');
SELECT ok(NOT has_function_privilege('anon','public.start_sleep(uuid,uuid,timestamptz,timestamptz,text)','EXECUTE'),'anon cannot start sleep');
SELECT ok(NOT has_table_privilege('anon','public.sleep_sessions','SELECT'),'anon has no raw grant');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
